using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.LoginPath="/Login";o.Cookie.Name="AssetForge.Auth";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;});builder.Services.AddAuthorization();builder.Services.AddRazorPages(o=>{o.Conventions.AuthorizeFolder("/");o.Conventions.AllowAnonymousToPage("/Login");});builder.Services.AddDbContext<AssetForgeDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("AssetForge")??"Data Source=assetforge.db"));var app=builder.Build();app.UseStaticFiles();app.UseRouting();app.UseAuthentication();app.UseAuthorization();app.MapRazorPages();
using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AssetForgeDbContext>();await db.Database.EnsureCreatedAsync();await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS People (Id INTEGER NOT NULL CONSTRAINT PK_People PRIMARY KEY AUTOINCREMENT, FullName TEXT NOT NULL, Email TEXT NULL, EmployeeNumber TEXT NULL, DepartmentId INTEGER NULL, Active INTEGER NOT NULL DEFAULT 1, CONSTRAINT FK_People_Departments_DepartmentId FOREIGN KEY (DepartmentId) REFERENCES Departments (Id) ON DELETE NO ACTION)");await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS Assignments (Id INTEGER NOT NULL CONSTRAINT PK_Assignments PRIMARY KEY AUTOINCREMENT, AssetId INTEGER NOT NULL, PersonId INTEGER NOT NULL, AssignedUtc TEXT NOT NULL, ExpectedReturnUtc TEXT NULL, ReturnedUtc TEXT NULL, IssueCondition TEXT NOT NULL, ReturnCondition TEXT NULL, HandoverReference TEXT NULL, IssueNotes TEXT NULL, ReturnNotes TEXT NULL, AssignedBy TEXT NOT NULL, ReturnedBy TEXT NULL, CONSTRAINT FK_Assignments_Assets_AssetId FOREIGN KEY (AssetId) REFERENCES Assets (Id) ON DELETE NO ACTION, CONSTRAINT FK_Assignments_People_PersonId FOREIGN KEY (PersonId) REFERENCES People (Id) ON DELETE NO ACTION)");if(!db.Categories.Any()){var laptop=new AssetCategory{Name="Laptop"};var phone=new AssetCategory{Name="Mobile phone"};var network=new AssetCategory{Name="Network equipment"};var hq=new Location{Name="Northbridge HQ"};var branch=new Location{Name="Riverside Office"};var it=new Department{Name="Technology"};var ops=new Department{Name="Operations"};db.AddRange(laptop,phone,network,hq,branch,it,ops);await db.SaveChangesAsync();db.Assets.AddRange(new Asset{AssetTag="AF-000101",Name="Latitude 7450",Manufacturer="Dell",Model="Latitude 7450",Status="Available",CategoryId=laptop.Id,LocationId=hq.Id,DepartmentId=it.Id},new Asset{AssetTag="AF-000102",Name="ThinkPad T14",Manufacturer="Lenovo",Model="T14 Gen 5",Status="Available",CategoryId=laptop.Id,LocationId=hq.Id,DepartmentId=ops.Id},new Asset{AssetTag="AF-000103",Name="iPhone 16",Manufacturer="Apple",Model="iPhone 16",Status="Available",CategoryId=phone.Id,LocationId=branch.Id,DepartmentId=ops.Id});await db.SaveChangesAsync();}if(!db.People.Any()){var depts=await db.Departments.OrderBy(x=>x.Id).ToListAsync();db.People.AddRange(new Person{FullName="Maya Bennett",Email="maya.bennett@example.test",EmployeeNumber="EMP-1042",DepartmentId=depts.First().Id},new Person{FullName="Elliot Reed",Email="elliot.reed@example.test",EmployeeNumber="EMP-1088",DepartmentId=depts.Last().Id},new Person{FullName="Sofia Clarke",Email="sofia.clarke@example.test",EmployeeNumber="EMP-1126",DepartmentId=depts.Last().Id});await db.SaveChangesAsync();}}
app.Run();
